var xpprogression = {};
class XPProgression {
  static levelFromXP(a) {
    return Math.min(
      XPProgression.MAX_LEVEL,
      Math.max(
        1,
        Math.floor(Math.sqrt(Math.max(0, Number(a) || 0) / 15.625) * 0.2),
      ),
    );
  }
  static badgeFromLevel(a) {
    return Math.min(
      XPProgression.BADGE_COUNT,
      Math.max(
        1,
        Math.floor((Number(a) || 0) / XPProgression.LEVELS_PER_BADGE) + 1,
      ),
    );
  }
}
XPProgression.MAX_LEVEL = 512;
XPProgression.BADGE_COUNT = 32;
XPProgression.LEVELS_PER_BADGE = 16;
